    private static function persistPlateletSample(array $sample,array $values):void{$id=(int)$sample['id'];$lcqh=array_key_exists('lcqh_code',$values)?trim((string)$values['lcqh_code']):(string)($sample['lcqh_code']??'');if(mb_strlen($lcqh)>80)throw new DomainException('Código LCQH deve ter no máximo 80 caracteres.');Database::connection()->prepare('UPDATE samples SET lcqh_code=:code WHERE id=:id')->execute(['code'=>$lcqh!==''?$lcqh:null,'id'=>$id]);if(($sample['lcqh_code']??null)!==($lcqh!==''?$lcqh:null))Auth::registerAudit('quality_sample.lcqh_code.update','samples',$id,['lcqh_code'=>$sample['lcqh_code']??null],['lcqh_code'=>$lcqh!==''?$lcqh:null]);PlateletResultService::save($id,$values);}
